enum PlanReason: Sendable, Hashable { case rotation; case manual; case frequency(muscle: MuscleGroup, done: Int, target: Int); case deload(DeloadTrigger?) }   // .deload(trigger) enquanto .pending, .deload(nil) durante .active
struct SessionPlan { ...campos existentes...; let isDeload: Bool; let reason: PlanReason? }
  init(programID:programName:programDayID:programDayName:exercises:generatedAt:isDeload: Bool = false, reason: PlanReason? = nil)

struct PlannerSettings: Sendable, Hashable {
  enum FrequencySelectorMode: String, Sendable, Hashable, CaseIterable { case auto, on, off }   // usável com @AppStorage
  static let frequencySelectorKey = "plannerFrequencySelector"   // "auto" | "on" | "off"
  static let deloadWeeksKey = "plannerDeloadWeeks"               // Int, padrão 6, 0 desliga (b)
  static let autoFrequencyMinimumDays = 4
  static let defaultDeloadWeeks = 6
  var frequencySelector: FrequencySelectorMode; var deloadWeeks: Int
  init(frequencySelector: FrequencySelectorMode = .auto, deloadWeeks: Int = 6)
  static func load(from defaults: UserDefaults) -> PlannerSettings
  func usesFrequencySelector(programDayCount: Int) -> Bool
}

@MainActor final class SessionPlanner: SessionPlanning
  init(modelContext: ModelContext,
       coordinator: any SessionCoordinating,
       progression: any ProgressionRule = DoubleProgressionRule(),
       selector: any WorkoutSelector = RotationSelector(),
       deloadDecisions: any DeloadDecisionsStoring = FakeDeloadDecisionsStore(),
       settings: @escaping () -> PlannerSettings = { PlannerSettings.load(from: .standard) },
       calendar: Calendar = .autoupdatingCurrent)
  // IMPORTANTE: em AppEnvironment.live() passe deloadDecisions: LiveDeloadDecisionsStore() (e guarde a mesma instância em AppEnvironment.deloadDecisions). O padrão é o Fake em memória (R9), que perde "Fazer semana leve agora"/"Seguir normal" ao relançar. preview() pode ficar com o padrão.

// SessionPlanning ganha (requisitos + padrão na extensão):
func deloadStatus(now: Date) throws -> DeloadStatus            // padrão .inactive; .inactive sem programa ativo ou sem dias
func requestDeload(now: Date) throws                            // grava manualRequestedAt = now SÓ se status == .inactive; senão no-op
func dismissDeload(now: Date) throws                            // SÓ em .pending: dismissedAt = now e manualRequestedAt = nil; senão no-op
func completedSessionSummaries() throws -> [SessionSummary]     // só status .completed, todos os programas, mais antiga primeiro (empate por id), com isDeload
func reviewInput(now: Date, recovery: RecoveryContext) throws -> ReviewInput?   // programa ativo; nil sem programa/dias; currentPrescriptions leves durante semana leve

// Decisões (Services/Decisions)
protocol DeloadDecisionsStoring: AnyObject { func load() -> DeloadDecisions; func save(_ decisions: DeloadDecisions) throws }
enum DeloadDecisionsStoreError: Error, Equatable { case storageUnavailable }
final class LiveDeloadDecisionsStore: DeloadDecisionsStoring { static let fileName = "deload-decisions.json"; let fileURL: URL?; init(fileURL: URL? = LiveDeloadDecisionsStore.defaultFileURL()); static func defaultFileURL() -> URL? }   // Application Support/PersonalTrainer/deload-decisions.json, escrita .atomic
final class FakeDeloadDecisionsStore: DeloadDecisionsStoring { private(set) var decisions: DeloadDecisions; private(set) var saveCount: Int; var saveError: (any Error)?; init(decisions: DeloadDecisions = DeloadDecisions()) }

// Comportamento: nextPlan usa FrequencyAwareSelector quando settings().usesFrequencySelector(dias) (metas e início da semana do UserSettingsModel), senão RotationSelector; reason = .deload(...) em semana leve, senão .frequency(grupo do dia mais longe da meta) ou .rotation. plan(forDayID:) sempre reason = .manual e isDeload = true também em .pending/.active. SessionCoordinator.startSession grava WorkoutSessionModel.isDeload = plan.isDeload; SessionSummaryMapper copia isDeload.

